import { fetchOrFail } from '@mlflow/mlflow/src/common/utils/FetchUtils';
import { NetworkRequestError } from '@databricks/web-shared/errors';

const INVALID_JSON_MESSAGE = 'Invalid JSON in request body';

export interface TryItError {
  message: string;
  responseBody?: string;
}

export interface UseTryItOptions {
  tryItRequestUrl: string;
}

export interface UseTryItResult {
  data: string | undefined;
  error: TryItError | undefined;
  isLoading: boolean;
  sendRequest: (body: string) => void;
  reset: () => void;
}

/**
 * Pretty-prints a raw response body as JSON when possible, falling back to the raw text otherwise.
 */
const prettyPrintJson = (text: string): string => {
  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
};

/**
 * React hook that manages sending a POST request to the given URL while tracking the response
 * data, error, and loading state. The request body is provided as a raw string; if it is not valid
 * JSON, the request is not sent and an "Invalid JSON in request body" error is surfaced.
 */
export const useTryIt = ({ tryItRequestUrl }: UseTryItOptions): UseTryItResult => {
  const mutation = useMutation<string, TryItError, string>({
    mutationFn: async (body: string): Promise<string> => {
      let parsed: unknown;
      try {
        parsed = JSON.parse(body);
      } catch {
        // Throwing before touching fetchOrFail guarantees no network request is made.
        throw { message: INVALID_JSON_MESSAGE } satisfies TryItError;
      }

      try {
        const response = await fetchOrFail(tryItRequestUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(parsed),
        });
        const responseText = await response.text();
        return prettyPrintJson(responseText);
      } catch (err) {
        // NetworkRequestError (and its subclasses) carry the originating HTTP response, whose body
        // we surface to the caller. Any other error is a non-HTTP failure with no response body.
        if (err instanceof NetworkRequestError) {
          let responseBody: string | undefined;
          if (err.response) {
            try {
              responseBody = prettyPrintJson(await err.response.text());
            } catch {
              responseBody = undefined;
            }
          }
          throw { message: err.message, responseBody } satisfies TryItError;
        }
        if (err instanceof Error) {
          throw { message: err.message } satisfies TryItError;
        }
        throw { message: String(err) } satisfies TryItError;
      }
    },
  });

  return {
    data: mutation.data,
    error: mutation.error ?? undefined,
    isLoading: mutation.isLoading,
    sendRequest: (body: string) => mutation.mutate(body),
    reset: () => mutation.reset(),
  };
};
