/**
 * Internal error thrown by the mutation. Carries the pretty-printed response body (when the failure
 * originated from an HTTP response) so it can be surfaced to the caller alongside the message.
 */
class TryItRequestError extends Error {
  responseBody?: string;

  constructor(message: string, responseBody?: string) {
    super(message);
    this.name = 'TryItRequestError';
    this.responseBody = responseBody;
  }
}

/**
 * Pretty-prints a raw response body as JSON when possible, falling back to the raw text otherwise.
