    error: mutation.error ? { message: mutation.error.message, responseBody: mutation.error.responseBody } : undefined,
    isLoading: mutation.isLoading,
    sendRequest: (body: string) => mutation.mutate(body),
    reset: () => mutation.reset(),
  };
